def create_existing_p16_drafts(apps, schema_editor):
    P16Assignment = apps.get_model("cases", "P16Assignment")
    P16Draft = apps.get_model("cases", "P16Draft")
    today = timezone.localdate()
    for assignment in P16Assignment.objects.filter(status="jaksa_ditunjuk").iterator():
        letter_date = assignment.assigned_at.date() if assignment.assigned_at else today
        P16Draft.objects.get_or_create(
            assignment=assignment,
            defaults={
                "draft_number": f"DRAFT/P-16/{assignment.pk:04d}/{letter_date.year}",
                "letter_date": letter_date,
                "generated_by_id": assignment.kasi_pidum_id,
            },
        )


